LABEL = {'titleDifferent': '타이틀 다름', 'trimDifferent': '트림 다름 또는 미확인', 'mileageGap': '주행거리 차이 40,000mi 초과',
         'runningUnknown': 'Run & drive 미확인', 'driveDifferent': '구동방식 다름 또는 미확인', 'engineDifferent': '엔진 사양 다름',
         'odometer': '주행거리 Not actual', 'buyNow': 'Buy Now 별도 거래', 'statusConflict': 'Sold / Reserve met No 불일치'}
norm = lambda s: re.sub(r'\s+', ' ', str(s or '')).strip().upper()
drive = lambda s: 'AWD' if re.search(r'AWD|ALL|4WD|4X4', norm(s)) else 'FWD' if re.search(r'FWD|FRONT', norm(s)) else norm(s) or None
def litres(s):
    m = re.search(r'(\d(?:\.\d+)?)\s*L\b', str(s or ''))
    return f'{float(m[1]):.1f}' if m else None

rows = []
for r in RECORDS:
    r = {k: html.unescape(v) if isinstance(v, str) else v for k, v in r.items()}
    t = str(r['targetLot']); car = by[t]; trims, drv, eng = TARGETS[t]
    title = re.sub(r'\s*title$', '', str(r['title'] or ''), flags=re.I).strip().capitalize() or '미표시'
    flags = []
    if title != 'Salvage': flags.append('titleDifferent')
    if norm(r['trim']) not in trims: flags.append('trimDifferent')
    if abs(r['miles'] - car['miles']) > 40000: flags.append('mileageGap')
    if not re.search(r'run (&|and) drive', str(r['condition'] or ''), re.I): flags.append('runningUnknown')
    if drive(r['drive']) != drv: flags.append('driveDifferent')
    if litres(r['engine']) and litres(r['engine']) != eng: flags.append('engineDifferent')
    if re.search(r'not actual|exempt|exceed', str(r.get('odometerStatus') or ''), re.I): flags.append('odometer')
    if r.get('buyNow'): flags.append('buyNow')
    if r['status'] == 'Sold' and r['reserveMet'] == 'No': flags.append('statusConflict')
    included = not flags and r['status'] == 'Sold' and r['reserveMet'] == 'Yes'
    target_damage = car['damage'].split('+')[0].strip().lower()
    damage_match = target_damage.split('/')[0] in str(r['damage']).lower()
    rows.append(dict(
        targetLot=t, lot=str(r['lot']), vin=r['vin'], vehicle=r['vehicle'], trim=r['trim'], price=int(r['price']), date=r['date'],
        miles=int(r['miles']), damage=r['damage'] + (f" + {r['secondaryDamage']}" if r.get('secondaryDamage') else ''), title=title,
        condition=r['condition'] or '미표시', location=r['location'], state=r['state'], reserveMet=r['reserveMet'] or '미표시',
        status=r['status'], engine=r['engine'], drive=r['drive'], source=r['source'], checkedAt='2026-09-23',
        targetRegion='KS', targetYard='KC', flags=flags, included=included,
        exclusion='' if included else '참고용: ' + (' · '.join(LABEL[f] for f in flags) or '판매·Reserve 미확정'),
        damageMatch=damage_match, mileageDifference=int(r['miles']) - car['miles'],
        similarity='reference' if not included else 'closer' if damage_match else 'damageDifferent'))

assert {r['targetLot'] for r in rows} <= set(TARGETS)
assert len({(r['targetLot'], r['vin']) for r in rows}) == len(rows), 'duplicate VIN for a target'
assert not {r['lot'] for r in rows} & set(TARGETS), 'a target lot was used as its own comparison'

comps['comparables'] += rows
summaries = {}
for t in sorted({r['targetLot'] for r in rows}):
    rs = [r for r in rows if r['targetLot'] == t]
    inc = sorted(r['price'] for r in rs if r['included'])
    med = statistics.median(inc) if len(inc) >= 2 else None
    car = by[t]
    summaries[t] = dict(targetLot=t, vehicle=car['vehicle'], count=len(inc), records=len(rs), median=med,
                        min=inc[0] if inc else None, max=inc[-1] if inc else None, bidCeiling=car['maxBid'],
                        ceilingMinusMedian=None if med is None else car['maxBid'] - med)
    car.update(comparisonAverage=sum(r['price'] for r in rs) / len(rs), comparisonAverageCount=len(rs),
               comparisonSampleCount=len(inc), comparisonMedian=med, comparisonRecords=len(rs), comparisonCheckedAt='2026-09-23')
comps['summaries'] += summaries.values()
comps['uniqueRecords'] = len({r['source'] for r in comps['comparables']})
comps['newUniqueRecords'] = len({r['source'] for r in rows})
comps['checkedAt'] = '2026-09-23'
(p / 'auction-comps.json').write_text(json.dumps(comps, ensure_ascii=False, indent=2) + '\n')
(p / 'combined80.json').write_text(json.dumps(cars, ensure_ascii=False, indent=2) + '\n')

for name in ['combined.html', 'index.html', 'suv.html']:
    text = (p / name).read_text()
    def patch(m):
        block = m[0]
        t = next((t for t in summaries if f'id="lot-{t}"' in block), None)
        if not t: return block
        car = by[t]
        block = re.sub(r'<span class="metric market-median">.*?</span>',
                       f'<span class="metric market-median"><small>유사 경매 수집 평균</small><b>${round(car["comparisonAverage"]):,}</b>'
                       f'<small>수집 {car["comparisonAverageCount"]}건 · 수수료 제외</small></span>', block, count=1, flags=re.S)
        if f'data-target="{t}"' not in block:
            block = block.replace('</article>', f'<div class="auction-slot" data-target="{t}" data-lang="ko"></div></article>')
        return block
    (p / name).write_text(re.sub(r'<article\b.*?</article>', patch, text, flags=re.S))

for name, old in [('auction-records.js', '20260917-rogue'), ('es.html', '20260923-refresh')]:
    text = (p / name).read_text()
    assert old in text
    (p / name).write_text(text.replace(old, '20260923-kc'))

kc = [c for c in cars if c['yard'] == 'KC']
assert all(c['comparisonAverage'] is not None for c in kc if c['id'] in summaries)
print(f'{len(rows)} records for {len(summaries)} KC lots; {sum(r["included"] for r in rows)} meet the inclusion rule. '
      f'KC lots with an average: {sum(c["comparisonAverage"] is not None for c in kc)}/{len(kc)}')
